// Initialisation de la mémoire anti-doublon
const staticData = $getWorkflowStaticData('node');
staticData.sentHistory = staticData.sentHistory || [];

const results = [];
const now = new Date();
// On se base sur l'heure de Paris pour le calcul des jours
const todayStr = now.toLocaleString("en-US", {timeZone: "Europe/Paris"});
const today = new Date(todayStr);
today.setHours(0, 0, 0, 0);

const items = $input.all();
let bookings = [];

// Extraction des bookings selon le format de réponse API
if (items.length > 0 && items[0].json.bookings) {
  bookings = items[0].json.bookings;
} else if (items.length > 0) {
  bookings = items.map(i => i.json);
}

for (const b of bookings) {
  // On ne traite que les RDV confirmés
  if (!b.startTime || b.status !== 'ACCEPTED') continue;

  const rdvDateRaw = new Date(b.startTime);
  // Conversion forcée en heure de Paris pour l'affichage et le calcul
  const rdvParisStr = rdvDateRaw.toLocaleString("en-US", {timeZone: "Europe/Paris"});
  const rdvParis = new Date(rdvParisStr);

  const rdvDateOnly = new Date(rdvParis.getFullYear(), rdvParis.getMonth(), rdvParis.getDate());

  // Calcul de la différence de jours (J-1 ou J-3)
  const diffDays = Math.round((rdvDateOnly.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

  let emailType = null;
  if (diffDays === 3) emailType = 'proof_j3';
  else if (diffDays === 1) emailType = 'proof_j1';

  if (!emailType) continue; // Sauter si pas J-3 ou J-1

  const bookingId = b.id || b.uid;
  const uniqueKey = `${bookingId}_${emailType}`;

  // Vérification anti-doublon
  if (!staticData.sentHistory.includes(uniqueKey)) {
    const attendee = b.attendees?.[0] || {};
    const name = attendee.name || b.title || 'Client';
    const email = attendee.email || b.responses?.email;

    // Vérifier que l'email est valide
    if (email && email.includes('@')) {
      results.push({
        json: {
          email: email,
          firstName: name.split(' ')[0],
          rdvDate: rdvParis.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' }),
          rdvTime: rdvParis.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }),
          emailType: emailType,
          meetingLink: b.meetingUrl || b.metadata?.videoCallUrl || ''
        }
      });
      // Ajout à l'historique
      staticData.sentHistory.push(uniqueKey);
    }
  }
}

// Limitation de la mémoire à 500 entrées
if (staticData.sentHistory.length > 500) staticData.sentHistory = staticData.sentHistory.slice(-500);

return results;
